/**
 * @method
 * @name scwin.checkRadio
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkRadio = function () {
    /* sdd-asis-lifecycle:begin checkRadio — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const checkRdArr = $('input[key=checkRd]');
    const leng = checkRdArr.length;
    if (leng > 0) {
        for (let i = 0; i < leng; i++) {
            const vl = $(checkRdArr[i]).val();
            const target = $(checkRdArr[i]).attr("target");
            const checkId = $('label[for*=' + target + ']:contains(' + vl + ')').attr("for");
            const tObj = $('#' + checkId);
            if (tObj.length > 0) {
                $('#' + checkId)[0].checked = true;
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkSelect
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkSelect = function () {
    /* sdd-asis-lifecycle:begin checkSelect — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const checkStArr = $('input[key=checkSt]');
    const leng = checkStArr.length;
    if (leng > 0) {
        for (let i = 0; i < leng; i++) {
            const vl = $(checkStArr[i]).val();
            const target = $(checkStArr[i]).attr("target");
            const tObj = $('#' + target);
            if (tObj.length > 0) {
                if (target === 'byinst_credit_valu_grd1' || target === 'byinst_credit_valu_grd2' || target === 'byinst_credit_valu_grd3' || target === 'byinst_credit_valu_grd4') {
                    if (vl !== '') {
                        $('#' + target).find("option[value='" + vl + "']").attr("selected", true);
                        $('#' + target + '_ck')[0].checked = true;
                        $('#' + target).attr("disabled", false);
                        $('#' + target).attr("style", "background:");
                    } else {
                        $('#' + target + '_ck')[0].checked = false;
                        $('#' + target).attr("disabled", true);
                    }
                } else {
                    $('#' + target).find('option:contains(' + vl + ')').attr("selected", true);
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkRegData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkRegData = function () {
    /* sdd-asis-lifecycle:begin checkRegData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const vl = dma_hiddenStore.get("ipt_regType");
    if (vl !== '') {
        const tObj = $('input[name=std_cd_apct_tp_cd][value="' + vl + '"]');
        if (tObj.length > 0) {
            $(tObj)[0].checked = true;
        }
    }
    const email = dma_hiddenStore.get("ipt_regEmail");
    if (email !== '') {
        const emails = email.split("@");
        if (emails.length > 0) {
            $c.util.getComponent('ipt_email01').setValue(emails[0]);
        }
        if (emails.length > 1) {
            $c.util.getComponent('ipt_email02').setValue(emails[1]);
        }
    }
    const tel = dma_hiddenStore.get("ipt_regTel");
    if (tel !== '') {
        const tels = tel.split("-");
        if (tels.length > 0) {
            $c.util.getComponent('ipt_ph01').setValue(tels[0]);
        }
        if (tels.length > 1) {
            $c.util.getComponent('ipt_ph02').setValue(tels[1]);
        }
        if (tels.length > 2) {
            $c.util.getComponent('ipt_ph03').setValue(tels[2]);
        }
    }
    const fax = dma_hiddenStore.get("ipt_regFax");
    if (fax !== '') {
        const faxs = fax.split("-");
        if (faxs.length > 0) {
            $c.util.getComponent('ipt_fax01').setValue(faxs[0]);
        }
        if (faxs.length > 1) {
            $c.util.getComponent('ipt_fax02').setValue(faxs[1]);
        }
        if (faxs.length > 2) {
            $c.util.getComponent('ipt_fax03').setValue(faxs[2]);
        }
    }
    const hpNo = $c.util.getComponent('ipt_encrypCellphoneNo').getValue();
    const hpNos = hpNo.split("-");
    if (hpNos.length > 0) {
        $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(hpNos[0]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(hpNos[1]);
    }
    if (hpNos.length > 1) {
        $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(hpNos[2]);
    }
    /* sdd-asis-lifecycle:end */
};


